PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://w3-id.org/md#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name ?point ?series
WHERE {
  ?point brick:hasName ?n .
  FILTER(?n IN ("Chiller02","CondPump01","CondPump02"))
  OPTIONAL { ?point ref:hasExternalReference ?ser ; ?ser ref:hasTimeseriesId ?series }
}

